// результаты audit / variables-check / audit-parity от 2026-11-12. Поле defaults — вариант по умолчанию набора в Figma.
// Поле todo — что осталось после пакета правок beta 2026-11-13 (умолчания, описания, min / max, порядок осей сделаны в Figma).

const PLASHKA = 'Плашка: слой `state/layer` × `state/hover` 6 % / `state/pressed` 10 %; Disabled — токены `*/disabled`';
const SELECT = 'Контрол выбора: слой `state/layer` на глифе, выбранное — `control/checked`';
const TEXTUAL = 'Текстовый: Hover / Pressed меняют цвет текста, подложки нет';
const NONE = 'нет: неинтерактивный элемент';
const ZONES = 'Зона нажатия ≥ `touch/min`: Web 24, касание 44 (слои `hit area · web` / `hit area · app`, проверка — Show hit area); безопасное поле — `control/safe-margin`.';
const FOCUS = 'Кольцо фокуса — только при навигации с клавиатуры, появляется сразу, без анимации (`service-layers.md`).';
const MOTION = 'Hover: слой 0 → 6 %, `motion/duration/feedback` (120 мс), `motion/easing/standard`. «Уменьшить движение»: длительности ≈ 0.';
const PLATFORMS = ['Размеры и плотность — из режима Platform (Web · Mobile web · iOS · Android); цвета от платформы не зависят.', 'Hover — только с указателем (Web); на касании Hover нет, Pressed остаётся.'];
const RTL = 'RTL: порядок слотов зеркалится (leading ↔ trailing), смысловые стрелки и шевроны отражаются, цифры и латиница — нет.';
const LONG = (n) => `Длинный текст: одна строка, усечение многоточием по max-width ${n}; полный текст — в \`title\` / тултипе.`;
const OK = '0 замечаний';
// Стенд 13.11 + перепроверка Dark 15.11 после принятия в Components `surface/raised` Dark → `neutral/700` (Tooltip, Toast, Suggest, List item).
const DARK15 = 'перепроверка Dark 15.11 пройдена (после принятия в Components `surface/raised` Dark → `neutral/700`): различим на L0–L2; на L3 приподнятая поверхность равна L3 и держится обводкой / тенью — правило, не дефект';
const STAND13 = 'полный крест 72 ячеек — на стенде 2026-11-13 просмотрены 24 (Light / Dark × EMCD / Geometria / WL × Web / iOS / Android на L0 и L1–L3 для EMCD Web), длинный текст, 6 языков, 200 %';

